// This file is generated by AI.

//! 项目与场景加载。
//!
//! 只做“读进来并保留行号”这一层; 语义检查、时间线编译在 `script` 模块完成。
//! 场景使用 `webgal-language-core` 的 `Scene`, 它与 LSP 共用一套语句解析。

use std::{
    collections::BTreeMap,
    fs,
    path::{Component, Path, PathBuf},
};

use walkdir::WalkDir;
use webgal_language_core::{
    resource::Config,
    sentence::{Scene, SentenceInfo},
};

use crate::{Error, Result, project::TemplateInfo};

/// WebGAL 的舞台坐标默认尺寸 (与 `game/config.txt` 缺省值一致)。
pub const DEFAULT_STAGE_SIZE: (u32, u32) = (2560, 1440);

/// 游戏配置 (`game/config.txt`)。
#[derive(Debug, Clone, Default, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GameConfig {
    /// 游戏标题。
    pub title: Option<String>,
    /// 全部配置项，同名键后者覆盖前者。
    pub values: BTreeMap<String, String>,
}

impl GameConfig {
    fn from_config(config: &Config) -> Self {
        let mut values = BTreeMap::new();
        for item in config.iter().filter(|item| item.is_config()) {
            values.insert(item.name.clone(), item.value.clone());
        }
        Self {
            title: values.get("Game_name").cloned(),
            values,
        }
    }
}

/// 一个场景文件。
#[derive(Debug)]
pub struct SceneEntry {
    /// 相对 `game/scene/` 的路径, 使用 `/`.
    pub name: String,
    /// 绝对路径.
    pub path: PathBuf,
    /// 解析后的场景.
    pub scene: Scene,
}

impl SceneEntry {
    /// 语句及其 1 起始行号.
    pub fn sentences(&self) -> impl Iterator<Item = (usize, &SentenceInfo<'_>)> {
        self.scene
            .sentences()
            .iter()
            .enumerate()
            .map(|(index, sentence)| (index + 1, sentence))
    }
}

/// 已加载的 WebGAL 项目。
#[derive(Debug)]
pub struct Project {
    root: PathBuf,
    game_dir: PathBuf,
    config: GameConfig,
    template: Option<TemplateInfo>,
    scenes: BTreeMap<String, SceneEntry>,
}

impl Project {
    /// 打开项目根目录 (包含 `game/`), 也接受直接指向 `game/` 的路径.
    pub fn open(path: impl Into<PathBuf>) -> Result<Self> {
        let input = path.into();
        if !input.is_dir() {
            return Err(Error::InvalidProject {
                path: input,
                missing: "目录".to_owned(),
            });
        }
        let input = fs::canonicalize(&input).map_err(|source| Error::Io {
            path: input,
            source,
        })?;

        let direct_game = input.join("game");
        let (root, game_dir) = if direct_game.is_dir() {
            (input.clone(), direct_game)
        } else if input
            .file_name()
            .is_some_and(|name| name.eq_ignore_ascii_case("game"))
            && input.join("config.txt").is_file()
        {
            let root = input
                .parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| input.clone());
            (root, input.clone())
        } else {
            return Err(Error::InvalidProject {
                path: input,
                missing: "game/".to_owned(),
            });
        };

        let config_path = game_dir.join("config.txt");
        if !config_path.is_file() {
            return Err(Error::InvalidProject {
                path: root,
                missing: "game/config.txt".to_owned(),
            });
        }
        let config_text = fs::read_to_string(&config_path).map_err(|source| Error::Io {
            path: config_path.clone(),
            source,
        })?;
        let config = GameConfig::from_config(&Config::from_str(&config_text));

        let scene_dir = game_dir.join("scene");
        if !scene_dir.is_dir() {
            return Err(Error::InvalidProject {
                path: root,
                missing: "game/scene/".to_owned(),
            });
        }

        let mut scenes = BTreeMap::new();
        for entry in WalkDir::new(&scene_dir).max_depth(1).follow_links(false) {
            let entry = entry.map_err(|error| Error::Io {
                path: scene_dir.clone(),
                source: std::io::Error::other(error),
            })?;
            if !entry.file_type().is_file()
                || !entry
                    .path()
                    .extension()
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("txt"))
            {
                continue;
            }
            let path = entry.into_path();
            let name = path
                .strip_prefix(&scene_dir)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/");
            let content = fs::read_to_string(&path).map_err(|source| Error::Io {
                path: path.clone(),
                source,
            })?;
            scenes.insert(
                name.clone(),
                SceneEntry {
                    name,
                    path,
                    scene: Scene::from_str(content),
                },
            );
        }

        if scenes.is_empty() {
            return Err(Error::InvalidProject {
                path: root,
                missing: "game/scene/*.txt".to_owned(),
            });
        }

        let template = TemplateInfo::load(&game_dir.join("template"));

        Ok(Self {
            root,
            game_dir,
            config,
            template,
            scenes,
        })
    }

    /// 项目根目录.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// `game/` 目录.
    pub fn game_dir(&self) -> &Path {
        &self.game_dir
    }

    /// 游戏配置.
    pub fn config(&self) -> &GameConfig {
        &self.config
    }

    /// 舞台尺寸 (`Stage_Width` × `Stage_Height`, 缺省 2560×1440).
    ///
    /// 脚本里的 `-transform` 坐标与模板 CSS 都按这个尺寸书写; 导出分辨率只决定
    /// 输出多大, 画幅 (宽高比) 必须跟随舞台, 否则构图会被拉伸。
    pub fn stage_size(&self) -> (u32, u32) {
        let read = |key: &str, fallback: u32| {
            self.config
                .values
                .get(key)
                .and_then(|value| value.trim().parse::<u32>().ok())
                .filter(|value| *value >= 64)
                .unwrap_or(fallback)
        };
        (
            read("Stage_Width", DEFAULT_STAGE_SIZE.0),
            read("Stage_Height", DEFAULT_STAGE_SIZE.1),
        )
    }

    /// 项目声明的 WebGAL 版本 (`webgal-engine.json` 的 `webgalVersion`)。
    ///
    /// 这是引擎包清单, 不是 MyGO 自己的 `version`; 4.6.4 起 `changeFigure` 的
    /// 立绘身份判定变了, 导出需要据此选择时间线口径。
    pub fn webgal_version(&self) -> Option<String> {
        let text = fs::read_to_string(self.root.join("webgal-engine.json")).ok()?;
        let value: serde_json::Value = serde_json::from_str(&text).ok()?;
        value
            .get("webgalVersion")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned)
    }

    /// 模板信息.
    pub fn template(&self) -> Option<&TemplateInfo> {
        self.template.as_ref()
    }

    /// 全部场景, 按名称排序.
    pub fn scenes(&self) -> impl Iterator<Item = (&str, &SceneEntry)> {
        self.scenes
            .iter()
            .map(|(name, entry)| (name.as_str(), entry))
    }

    /// 按名称取场景; 允许省略 `.txt`.
    pub fn scene(&self, name: &str) -> Option<&SceneEntry> {
        self.scenes.get(name).or_else(|| {
            if name.ends_with(".txt") {
                None
            } else {
                self.scenes.get(&format!("{name}.txt"))
            }
        })
    }

    /// 解析资源路径; 仅返回真实存在的文件.
    ///
    /// `kind_dir` 是 `game/` 下的资源目录名 (`background`, `figure`, ...).
    pub fn asset_path(&self, kind_dir: &str, raw: &str) -> Option<PathBuf> {
        let relative = normalize_resource(kind_dir, raw)?;
        let base = self.game_dir.join(kind_dir);
        let candidate = base.join(&relative);
        if candidate.is_file() {
            return Some(candidate);
        }

        if kind_dir == "scene" && candidate.extension().is_none() {
            let with_txt = candidate.with_extension("txt");
            return with_txt.is_file().then_some(with_txt);
        }

        let extensions: &[&str] = match kind_dir {
            "background" => &["png", "jpg", "jpeg", "webp", "bmp", "gif"],
            "figure" => &["png", "jpg", "jpeg", "webp", "bmp", "gif"],
            "bgm" | "vocal" => &["mp3", "wav", "ogg", "flac"],
            "video" => &["mp4", "webm", "mkv", "ogg"],
            _ => &[],
        };
        if candidate.extension().is_none() {
            for extension in extensions {
                let mut with_extension = candidate.clone();
                with_extension.set_extension(extension);
                if with_extension.is_file() {
                    return Some(with_extension);
                }
            }
        }
        None
    }
}

/// 规范化资源值: 去掉 `game/`、资源根前缀, 拒绝绝对路径与 `..`.
fn normalize_resource(kind_dir: &str, raw: &str) -> Option<PathBuf> {
    let mut value = raw.trim().replace('\\', "/");
    if let Some(rest) = value.strip_prefix("game/") {
        value = rest.to_owned();
    }
    if let Some(rest) = value.strip_prefix(&format!("{kind_dir}/")) {
        value = rest.to_owned();
    }
    if value.is_empty() {
        return None;
    }

    let path = Path::new(&value);
    if path.is_absolute()
        || path.components().any(|component| {
            matches!(
                component,
                Component::ParentDir | Component::RootDir | Component::Prefix(_)
            )
        })
    {
        return None;
    }
    Some(path.to_path_buf())
}
